type UserData = {
    id: number;
    name: string;
    email?: string;
};

// type を使って関数の引数と返り値を定義
function validateUser(user: UserData): boolean {
    return user.id > 0 && user.name.length > 0;
}

// オブジェクトを作成
const data: UserData = {
    id: 100,
    name: "新規ユーザー"
};

// 型检查（型エラーにならないように使う）
validateUser(data); // ここでは問題ありません
```

